const listTrafficAlerts = `-- name: ListTrafficAlerts :many
SELECT id, tenant_id, tenancy, threshold, auto_shutdown, notification_email,
       enabled, last_notification, created_at, updated_at, statistics_enabled, cloud_type
FROM traffic_alert ORDER BY tenant_id
`

func (q *Queries) ListTrafficAlerts(ctx context.Context) ([]TrafficAlert, error) {
	rows, err := q.db.QueryContext(ctx, listTrafficAlerts)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TrafficAlert{}
	for rows.Next() {
		var i TrafficAlert
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Tenancy,
			&i.Threshold,
			&i.AutoShutdown,
			&i.NotificationEmail,
			&i.Enabled,
			&i.LastNotification,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StatisticsEnabled,
			&i.CloudType,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

