const upsertTrafficAlert = `-- name: UpsertTrafficAlert :exec
INSERT INTO traffic_alert (
    tenant_id, tenancy, threshold, auto_shutdown, notification_email, enabled, cloud_type,
    statistics_enabled, created_at, updated_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(tenant_id) DO UPDATE SET
    threshold = excluded.threshold,
    auto_shutdown = excluded.auto_shutdown,
    notification_email = excluded.notification_email,
    enabled = excluded.enabled,
    statistics_enabled = excluded.statistics_enabled,
    updated_at = excluded.updated_at
`

type UpsertTrafficAlertParams struct {
	TenantID          int64          `json:"tenant_id"`
	Tenancy           string         `json:"tenancy"`
	Threshold         float64        `json:"threshold"`
	AutoShutdown      int64          `json:"auto_shutdown"`
	NotificationEmail sql.NullString `json:"notification_email"`
	Enabled           int64          `json:"enabled"`
	CloudType         sql.NullInt64  `json:"cloud_type"`
	StatisticsEnabled int64          `json:"statistics_enabled"`
	CreatedAt         string         `json:"created_at"`
	UpdatedAt         sql.NullString `json:"updated_at"`
}

func (q *Queries) UpsertTrafficAlert(ctx context.Context, arg UpsertTrafficAlertParams) error {
	_, err := q.db.ExecContext(ctx, upsertTrafficAlert,
		arg.TenantID,
		arg.Tenancy,
		arg.Threshold,
		arg.AutoShutdown,
		arg.NotificationEmail,
		arg.Enabled,
		arg.CloudType,
		arg.StatisticsEnabled,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	return err
}
